import networkx as nx
import json
import os
import pandas as pd
from typing import Dict, List


def search_algorithm(src, dsts, G, num_partitions):
    """Build a capacity-feasible partition-aware directed Steiner broadcast MILP."""
    import math
    import numpy as np
    from scipy.optimize import milp, Bounds, LinearConstraint
    from scipy.sparse import coo_matrix

    topology = BroadCastTopology(src, dsts, num_partitions)
    terminals = list(dict.fromkeys(d for d in dsts if d != src))
    partitions = max(1, int(num_partitions))

    if not terminals:
        for dst in dsts:
            for partition in range(num_partitions):
                topology.set_dst_partition_paths(dst, partition, [])
        return topology

    h = G.copy()
    h.remove_edges_from(
        list(h.in_edges(src)) + list(nx.selfloop_edges(h)) +
        [(u, v) for u, v, d in h.edges(data=True)
         if d.get("cost") is None or not math.isfinite(float(d["cost"]))]
    )

    reachable = nx.descendants(h, src) | {src}
    for terminal in terminals:
        if terminal not in reachable:
            raise nx.NetworkXNoPath("No priced route from %s to %s" % (src, terminal))
    useful = {src} | set(terminals)
    for terminal in terminals:
        useful.update(nx.ancestors(h, terminal) & reachable)
    h = h.subgraph(useful).copy()

    nodes = list(h.nodes)
    node_id = {node: i for i, node in enumerate(nodes)}
    arcs = list(h.edges())
    n, m, k = len(nodes), len(arcs), len(terminals)
    costs = np.array([float(h[u][v]["cost"]) for u, v in arcs])

    # x[p,e] activates a transmission of partition p over e.  Every
    # destination commodity for that same partition may reuse x[p,e].
    x_count = partitions * m
    flow_count = partitions * k * m
    total_variables = x_count + flow_count

    def x_index(p, e):
        return p * m + e

    def f_index(p, t, e):
        return x_count + (p * k + t) * m + e

    rows, cols, values = [], [], []
    lower, upper = [], []
    row = 0

    # One unit path from src to every (partition, destination) pair.
    for p in range(partitions):
        for t, terminal in enumerate(terminals):
            for node in nodes:
                demand = 1.0 if node == src else -1.0 if node == terminal else 0.0
                for e, (u, v) in enumerate(arcs):
                    if u == node:
                        rows.append(row)
                        cols.append(f_index(p, t, e))
                        values.append(1.0)
                    if v == node:
                        rows.append(row)
                        cols.append(f_index(p, t, e))
                        values.append(-1.0)
                lower.append(demand)
                upper.append(demand)
                row += 1

    # A terminal flow can use an arc only when its partition transmission is
    # activated.  This permits multicast sharing within, but never between,
    # partitions.
    for p in range(partitions):
        for t in range(k):
            for e in range(m):
                rows.extend((row, row))
                cols.extend((f_index(p, t, e), x_index(p, e)))
                values.extend((1.0, -1.0))
                lower.append(-np.inf)
                upper.append(0.0)
                row += 1

    # Normalize input rate to one and split it evenly across partitions.
    # Edges without a positive throughput remain usable because some input
    # graphs provide cost-only profiles; explicitly rated links are constrained.
    partition_rate = 1.0 / partitions
    for e, (u, v) in enumerate(arcs):
        throughput = h[u][v].get("throughput")
        if throughput is not None and math.isfinite(float(throughput)) and float(throughput) > 0:
            for p in range(partitions):
                rows.append(row)
                cols.append(x_index(p, e))
                values.append(partition_rate)
            lower.append(-np.inf)
            upper.append(float(throughput))
            row += 1

    matrix = coo_matrix(
        (values, (rows, cols)), shape=(row, total_variables)
    ).tocsr()
    objective = np.concatenate((
        np.tile(costs / partitions, partitions),
        np.zeros(flow_count)
    ))
    integrality = np.concatenate((
        np.ones(x_count),
        np.zeros(flow_count)
    ))

    selected_by_partition = None
    try:
        result = milp(
            c=objective,
            integrality=integrality,
            bounds=Bounds(np.zeros(total_variables), np.ones(total_variables)),
            constraints=LinearConstraint(
                matrix, np.asarray(lower), np.asarray(upper)
            ),
            options={"time_limit": 120},
        )
        if result.x is not None:
            candidate = []
            valid = True
            for p in range(partitions):
                selected = {
                    arcs[e] for e in range(m)
                    if result.x[x_index(p, e)] > 0.5
                }
                tree = nx.DiGraph()
                tree.add_edges_from(selected)
                if not all(nx.has_path(tree, src, terminal) for terminal in terminals):
                    valid = False
                    break
                candidate.append(tree)
            if valid:
                selected_by_partition = candidate
    except Exception:
        selected_by_partition = None

    # Cost-only fallback remains partition-aware in its output representation.
    if selected_by_partition is None:
        base = nx.DiGraph()
        for terminal in terminals:
            path = nx.shortest_path(h, src, terminal, weight="cost")
            base.add_edges_from(zip(path, path[1:]))
        selected_by_partition = [base.copy() for _ in range(partitions)]

    for partition, tree in enumerate(selected_by_partition):
        for dst in dsts:
            if dst == src:
                edges = []
            else:
                path = nx.shortest_path(tree, src, dst)
                edges = [[u, v, G[u][v]] for u, v in zip(path, path[1:])]
            topology.set_dst_partition_paths(dst, partition, edges)
    return topology


class SingleDstPath(Dict):
    partition: int
    edges: List[List]  # [[src, dst, edge data]]


class BroadCastTopology:
    def __init__(self, src: str, dsts: List[str], num_partitions: int = 4, paths: Dict[str, SingleDstPath] = None):
        self.src = src  # single str
        self.dsts = dsts  # list of strs
        self.num_partitions = num_partitions

        # dict(dst) --> dict(partition) --> list(nx.edges)
        # example: {dst1: {partition1: [src->node1, node1->dst1], partition 2: [src->dst1]}}
        if paths is not None:
            self.paths = paths
            self.set_graph()
        else:
            self.paths = {dst: {str(i): None for i in range(num_partitions)} for dst in dsts}

    def get_paths(self):
        print(f"now the set path is: {self.paths}")
        return self.paths

    def set_num_partitions(self, num_partitions: int):
        self.num_partitions = num_partitions

    def set_dst_partition_paths(self, dst: str, partition: int, paths: List[List]):
        """
        Set paths for partition = partition to reach dst
        """
        partition = str(partition)
        self.paths[dst][partition] = paths

    def append_dst_partition_path(self, dst: str, partition: int, path: List):
        """
        Append path for partition = partition to reach dst
        """
        partition = str(partition)
        if self.paths[dst][partition] is None:
            self.paths[dst][partition] = []
        self.paths[dst][partition].append(path)

def make_nx_graph(cost_path=None, throughput_path=None, num_vms=1):
    """
    Default graph with capacity constraints and cost info
    nodes: regions, edges: links
    per edge:
        throughput: max tput achievable (gbps)
        cost: $/GB
        flow: actual flow (gbps), must be < throughput, default = 0
    """
    # Use relative path from this file's location
    current_dir = os.path.dirname(os.path.abspath(__file__))

    if cost_path is None:
        cost = pd.read_csv(os.path.join(current_dir, "profiles/cost.csv"))
    else:
        cost = pd.read_csv(cost_path)

    if throughput_path is None:
        throughput = pd.read_csv(os.path.join(current_dir, "profiles/throughput.csv"))
    else:
        throughput = pd.read_csv(throughput_path)

    G = nx.DiGraph()
    for _, row in throughput.iterrows():
        if row["src_region"] == row["dst_region"]:
            continue
        G.add_edge(row["src_region"], row["dst_region"], cost=None, throughput=num_vms * row["throughput_sent"] / 1e9)

    for _, row in cost.iterrows():
        if row["src"] in G and row["dest"] in G[row["src"]]:
            G[row["src"]][row["dest"]]["cost"] = row["cost"]

    # some pairs not in the cost grid
    no_cost_pairs = []
    for edge in G.edges.data():
        src, dst = edge[0], edge[1]
        if edge[-1]["cost"] is None:
            no_cost_pairs.append((src, dst))
    print("Unable to get costs for: ", no_cost_pairs)

    return G


# EVOLVE-BLOCK-END

# Helper functions that won't be evolved
def create_broadcast_topology(src: str, dsts: List[str], num_partitions: int = 4):
    """Create a broadcast topology instance"""
    return BroadCastTopology(src, dsts, num_partitions)

def run_search_algorithm(src: str, dsts: List[str], G, num_partitions: int):
    """Run the search algorithm and return the topology"""
    return search_algorithm(src, dsts, G, num_partitions)

